def _log_mode(config, events=None):
    """record/replay 按 config 形状选模式：fdb、forward、stp、loop-detect、
    link-forward、link-state、forward-static、forward-stp、forward-check/
    forward-decode（共享 ports,age,max_frame 三键配置，按帧形状区分）、
    stp-check/stp-decode（共享七键配置，按事件帧形状区分）、
    forward-stp-storm、lag、mirror、acl、acl-check、qos、qos-check、
    security-check、mirror-check、lag-check、storm-check 或 port-security。

    events 非 None 时用于区分共享配置形状的两种模式：三键配置的非空帧
    数组含 src（八键）按 forward-check，含 data（t/port/data 原始帧）按
    forward-decode；两种帧形状混用报 InvalidInput；空数组沿用既有
    forward-decode 路由（既有日志字节不变）。stp 七键配置的非链路帧含
    src（九键）按 stp-check，含 data（t/port/data 原始帧）按 stp-decode；
    两种帧形状混用报 InvalidInput；仅链路项或空事件沿用既有 stp-decode
    路由（既有日志字节不变）。
    """
    if isinstance(config, dict):
        keys = frozenset(config)
        # 恰含 ports,age 且 ports 为字符串数组时为 fdb 模式（forward 旧
        # 入口的 ports 为对象数组，形状不重叠）
        if keys == CONFIG_KEYS and isinstance(
            config.get("ports"), list
        ) and all(isinstance(p, str) for p in config["ports"]):
            return "fdb"
        # 恰含 ports,age 且 ports 为非空对象数组时为 forward 模式，旧式
        # access（name/vlan/up）与新式 802.1Q（name/mode/pvid/allowed/
        # untagged/up）两种端口形状均沿用 forward 入口识别与校验
        if (
            keys == CONFIG_KEYS
            and isinstance(config.get("ports"), list)
            and bool(config["ports"])
            and all(isinstance(p, dict) for p in config["ports"])
        ):
            return "forward"
        if keys == STP_CONFIG_KEYS:
            return "stp"
        if keys == LOOP_CONFIG_KEYS:
            return "loop"
        if keys == LINK_FORWARD_CONFIG_KEYS:
            return "link_forward"
        if keys == LINK_STATE_CONFIG_KEYS:
            return "link_state"
        if keys == FORWARD_STATIC_CONFIG_KEYS:
            return "forward_static"
        if keys == FORWARD_STP_CONFIG_KEYS:
            return "forward_stp"
        if keys == FORWARD_CHECK_CONFIG_KEYS:
            # forward-check 与 forward-decode 共享三键配置：非空帧数组含
            # src（八键）按 forward-check，含 data 按 forward-decode，两种
            # 帧形状混用即非法输入；空数组沿用既有 forward-decode 路由
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == FORWARD_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                else:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "forward_check" if saw_src else "forward_decode"
        if keys == STP_CHECK_CONFIG_KEYS:
            # stp-check 与 stp-decode 共享七键配置：非链路帧含 src 按
            # stp-check，含 data 按 stp-decode，两种帧形状混用即非法输入
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == STP_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys != STP_EVENT_KEYS:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "stp_check" if saw_src else "stp_decode"
        if keys == STORM_CONFIG_KEYS:
            return "forward_stp_storm"
        if keys == LAG_CONFIG_KEYS:
            return "lag"
        if keys == MIRROR_CONFIG_KEYS:
            return "mirror"
        if keys == ACL_CONFIG_KEYS:
            return "acl"
        if keys == ACL_CHECK_CONFIG_KEYS:
            return "acl_check"
        if keys == QOS_CONFIG_KEYS:
            return "qos"
        if keys == QOS_CHECK_CONFIG_KEYS:
            return "qos_check"
        if keys == SECURITY_CHECK_CONFIG_KEYS:
            return "security_check"
        if keys == MIRROR_CHECK_CONFIG_KEYS:
            return "mirror_check"
        if keys == LAG_CHECK_CONFIG_KEYS:
            return "lag_check"
        if keys == STORM_CHECK_CONFIG_KEYS:
            return "storm_check"
    return "security"


def _run_fdb(config, events, observe, max_work=None):
    """record/replay fdb 模式：校验 fdb 配置与事件并执行仿真。

    语义同 fdb 子命令；max_work 非 None 时（record/replay）全量语义校验后
    先按 fdb 公式（逐事件累计 K+1，K 为老化前表项数）以独立空映射无副作用
    预演，首次超过即抛 FdbWorkLimit，不正式仿真。返回 (fdb 结果 dict,
    observer 或 None)；每项 output 恒 None，applied 与 version 由
    _build_log_doc/_verify_records 按 FDB 是否实际改变计算。
    """
    ports, age = validate_config(config)
    fdb_events = validate_events(events, ports)
    if max_work is not None:
        # 与 fdb 入口同一公式：独立空 FDB，无副作用
        fdb_work(fdb_events, age, max_work)
    observer = {} if observe else None
    result = simulate(fdb_events, age, observer=observer)
    return result, observer


def _run_stp(config, events, observe, max_work=None):
    """record/replay STP 模式：校验 stp 配置与事件并执行仿真。

    语义同 stp 子命令；max_work 非 None 时（record）全量语义校验后先按
    stp 公式无副作用预演（在 _stp_run 内、正式输出前完成），首次超过即
    抛 StpWorkLimit，不正式仿真。返回 (stp 结果 dict, observer 或 None)。
    """
    bridges, links, delay = validate_stp_config(config)
    link_ids = {link["id"] for link in links}
    stp_events = validate_stp_events(events, link_ids)
    observer = {} if observe else None
    result = _stp_run(
        bridges, links, delay, stp_events, max_work, observer=observer
    )
    return result, observer


def _run_loop_detect(config, events, observe, max_work=None):
    """record/replay 环路模式：校验 loop-detect 配置与事件并执行仿真。

    语义同 loop-detect 子命令；工作量预演（V*(L+1)*(事件数+1)）在
    loop_detect 内、正式仿真前无副作用完成，超限抛 LoopWorkLimit。
    返回 (loop-detect 结果 dict, observer 或 None)。
